---@class QuestieItemStartFixes
local QuestieItemStartFixes = QuestieLoader:CreateModule("QuestieItemStartFixes")
-------------------------
--Import modules.
-------------------------
---@type QuestieDB
local QuestieDB = QuestieLoader:ImportModule("QuestieDB");


function QuestieItemStartFixes:LoadAutomaticQuestStarts()
    local itemKeys = QuestieDB.itemKeys

  --! This file is automatically generated from wowhead data by looking at all items that starts a quest and correcting it.
  return {
      --* Item 1307 https://wotlk.wowhead.com/wotlk/item=1307
      --* Starts: The Collector(123)(https://wotlk.wowhead.com/wotlk/quest=123)
      [1307] = {
        [itemKeys.startQuest] = 123,
      },
      --* Item 1357 https://wotlk.wowhead.com/wotlk/item=1357
      --* Starts: Captain Sanders' Hidden Treasure(136)(https://wotlk.wowhead.com/wotlk/quest=136)
      [1357] = {
        [itemKeys.startQuest] = 136,
      },
    }
end
